from __future__ import absolute_import
from taf.ul.oam.selenium_rap_manager.common import TabBar, LocalBasicPage
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException, StaleElementReferenceException
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Tool(LocalBasicPage):
    _TOOL_TAB_XPATH = '//span[text()="Tools"]'
    _ENABLE_XPATH_RESTRICTED_ROOT_ACCESS = '//div[contains(@class,"restricted-root-access-state")]/..//div//button[text()="Enable"]'
    _POP_UP_ENABLE_XPATH_RESTRICTED_ROOT_ACCESS = '//div[@id="EnableAccessConfirmationDialog"]//button[text()="Enable"]'
    _DISABLE_XPATH_RESTRICTED_ROOT_ACCESS = '//div[contains(@class,"restricted-root-access-state")]/..//div//button[text()="Disable"]'
    _POP_UP_DISABLE_XPATH_RESTRICTED_ROOT_ACCESS = '//div[@id="DisableAccessConfirmationDialog"]//button[text()="Disable"]'
    _ENABLE_XPATH_ETH_PORT_SECURITY = '//div[contains(@class,"ethernet-port-security-state")]/..//div//button[text()="Enable"]'
    _POP_UP_ENABLE_XPATH_ETH_PORT_SECURITY = '//div[@id="EnableSecurityConfirmationDialog"]//button[text()="Enable"]'
    _DISABLE_XPATH_ETH_PORT_SECURITY = '//div[contains(@class,"ethernet-port-security-state")]/..//div//button[text()="Disable"]'
    _POP_UP_DISABLE_XPATH_ETH_PORT_SECURITY = '//div[@id="DisableSecurityConfirmationDialog"]//button[text()="Disable"]'
    _DROP_DOWN_SERVICE_ACCOUNT_SSH_STATUS = '//*[@id="sshStateDropdown"]/button'
    _ENABLE_XPATH_SERVICE_ACCOUNT_SSH_STATUS = '//*[@id="sshStateDropdown"]/ul/li[1]/a/span'
    _DISABLE_XPATH_SERVICE_ACCOUNT_SSH_STATUS = '//*[@id="sshStateDropdown"]/ul/li[2]/a/span'
    _DROP_DOWN_SERVICE_PORT_STATUS = '//*[@id="rndPortStateDropdown"]/button'
    _ENABLE_XPATH_SERVICE_PORT_STATUS = '//*[@id="rndPortStateDropdown"]/ul/li[1]/a/span'
    _DISABLE_XPATH_SERVICE_PORT_STATUS = '//*[@id="rndPortStateDropdown"]/ul/li[2]/a/span'
    _ACCESS_SEND_XPATH = '//*[@id="service-access-change-btn"]'
    _WARNING_XPATH_RESTRICTED_ROOT_ACCESS = '//*[@id="disabledButtonsInfo"]/span/span[2]'
    _GET_SERVICE_ACCOUNT_SSH_STATUS = '// *[ @ id = "sshStateDropdown"] / button / span[1] / span'
    _GET_SERVICE_PORT_STATUS = '// *[ @ id = "rndPortStateDropdown"] / button / span[1] / span'

    def __init__(self, driver):
        super(Tool, self).__init__(driver)
        self._tab_bar = TabBar(driver)
        self._tab_bar._click_tab(self._TOOL_TAB_XPATH)

    def enable_restricted_root_access(self):
        try:
            if self._is_web_element_enabled((By.XPATH, self._ENABLE_XPATH_RESTRICTED_ROOT_ACCESS), 20) and \
                    not self._is_web_element_enabled((By.XPATH, self._WARNING_XPATH_RESTRICTED_ROOT_ACCESS), 20):
                self.click_enabled_element((By.XPATH, self._ENABLE_XPATH_RESTRICTED_ROOT_ACCESS))
                self._wait_for_element_by((By.XPATH, self._POP_UP_ENABLE_XPATH_RESTRICTED_ROOT_ACCESS), 20)
                self.click_enabled_element((By.XPATH, self._POP_UP_ENABLE_XPATH_RESTRICTED_ROOT_ACCESS))
            else:
                logger.info("enable_restricted_root_access configuration already exists in the WEB-UI")
        except TimeoutException as Error:
            raise Exception('Unstable Web-UI for setting the configuration: {} '.format(Error))

    def disable_restricted_root_access(self):
        try:
            if self._is_web_element_enabled((By.XPATH, self._DISABLE_XPATH_RESTRICTED_ROOT_ACCESS), 20) and \
                    not self._is_web_element_enabled((By.XPATH, self._WARNING_XPATH_RESTRICTED_ROOT_ACCESS), 20):
                self.click_enabled_element((By.XPATH, self._DISABLE_XPATH_RESTRICTED_ROOT_ACCESS))
                self._wait_for_element_by((By.XPATH, self._POP_UP_DISABLE_XPATH_RESTRICTED_ROOT_ACCESS), 20)
                self.click_enabled_element((By.XPATH, self._POP_UP_DISABLE_XPATH_RESTRICTED_ROOT_ACCESS))
            else:
                logger.info("disable_restricted_root_access configuration already exists in the WEB-UI")
        except TimeoutException as Error:
            raise Exception('Unstable Web-UI for setting the configuration: {} '.format(Error))

    def enable_ethernet_port_security(self):
        try:
            if self._is_web_element_enabled((By.XPATH, self._ENABLE_XPATH_ETH_PORT_SECURITY), 20):
                self.click_enabled_element((By.XPATH, self._ENABLE_XPATH_ETH_PORT_SECURITY))
                self._wait_for_element_by((By.XPATH, self._POP_UP_ENABLE_XPATH_ETH_PORT_SECURITY), 20)
                self.click_enabled_element((By.XPATH, self._POP_UP_ENABLE_XPATH_ETH_PORT_SECURITY))
            else:
                logger.info("enable_ethernet_port_security configuration already exists in the WEB-UI")
        except TimeoutException as Error:
            raise Exception('Unstable Web-UI for setting the configuration: {} '.format(Error))

    def disable_ethernet_port_security(self):
        try:
            if self._is_web_element_enabled((By.XPATH, self._DISABLE_XPATH_ETH_PORT_SECURITY), 20):
                self.click_enabled_element((By.XPATH, self._DISABLE_XPATH_ETH_PORT_SECURITY))
                self._wait_for_element_by((By.XPATH, self._POP_UP_DISABLE_XPATH_ETH_PORT_SECURITY), 20)
                self.click_enabled_element((By.XPATH, self._POP_UP_DISABLE_XPATH_ETH_PORT_SECURITY))
            else:
                logger.info("disable_ethernet_port_security configuration already exists in the WEB-UI")
        except TimeoutException as Error:
            raise Exception('Unstable Web-UI for setting the configuration: {} '.format(Error))

    def enable_service_account_ssh(self):
        try:
            if self.get_text_by_xpath_until_element_visible(self._GET_SERVICE_ACCOUNT_SSH_STATUS,
                                                            timeout=20) != "Enabled":
                self.click_enabled_element((By.XPATH, self._DROP_DOWN_SERVICE_ACCOUNT_SSH_STATUS), 20)
                self.click_enabled_element((By.XPATH, self._ENABLE_XPATH_SERVICE_ACCOUNT_SSH_STATUS))
                if self._is_web_element_enabled((By.XPATH, self._ACCESS_SEND_XPATH), 20):
                    self.click_enabled_element((By.XPATH, self._ACCESS_SEND_XPATH))
            else:
                logger.info("enable_service_account_ssh configuration already exists in the WEB-UI")
        except (TimeoutException, StaleElementReferenceException) as Error:
            raise Exception('Unstable Web-UI for setting the configuration: {} '.format(Error))

    def disable_service_account_ssh(self):
        try:
            if self.get_text_by_xpath_until_element_visible(self._GET_SERVICE_ACCOUNT_SSH_STATUS,
                                                            timeout=20) != "Disabled":
                self.click_enabled_element((By.XPATH, self._DROP_DOWN_SERVICE_ACCOUNT_SSH_STATUS), 20)
                self.click_enabled_element((By.XPATH, self._DISABLE_XPATH_SERVICE_ACCOUNT_SSH_STATUS))
                if self._is_web_element_enabled((By.XPATH, self._ACCESS_SEND_XPATH), 20):
                    self.click_enabled_element((By.XPATH, self._ACCESS_SEND_XPATH))
            else:
                logger.info("disable_service_account_ssh configuration already exists in the WEB-UI")
        except (TimeoutException, StaleElementReferenceException) as Error:
            raise Exception('Unstable Web-UI for setting the configuration: {} '.format(Error))

    def enable_service_port(self):
        try:
            if self.get_text_by_xpath_until_element_visible(self._GET_SERVICE_PORT_STATUS, timeout=20) != "Enabled":
                self.click_enabled_element((By.XPATH, self._DROP_DOWN_SERVICE_PORT_STATUS), 20)
                self.click_enabled_element((By.XPATH, self._ENABLE_XPATH_SERVICE_PORT_STATUS))
                if self._is_web_element_enabled((By.XPATH, self._ACCESS_SEND_XPATH), 20):
                    self.click_enabled_element((By.XPATH, self._ACCESS_SEND_XPATH))
            else:
                logger.info("enable_service_port configuration already exists in the WEB-UI")
        except (TimeoutException, StaleElementReferenceException) as Error:
            raise Exception('Unstable Web-UI for setting the configuration: {} '.format(Error))

    def disable_service_port(self):
        try:
            if self.get_text_by_xpath_until_element_visible(self._GET_SERVICE_PORT_STATUS, timeout=20) != "Disabled":
                self.click_enabled_element((By.XPATH, self._DROP_DOWN_SERVICE_PORT_STATUS), 20)
                self.click_enabled_element((By.XPATH, self._DISABLE_XPATH_SERVICE_PORT_STATUS))
                if self._is_web_element_enabled((By.XPATH, self._ACCESS_SEND_XPATH), 20):
                    self.click_enabled_element((By.XPATH, self._ACCESS_SEND_XPATH))
            else:
                logger.info("disable_service_port configuration already exists in the WEB-UI")
        except (TimeoutException, StaleElementReferenceException) as Error:
            raise Exception('Unstable Web-UI for setting the configuration: {} '.format(Error))
